// Presentation-only facts export. Statistics remain owned by scripts/intensity_analysis.py.
const fs = require("fs");
const path = require("path");
module.exports = function writeFacts(X) {
  const { D, C, S, DS, SHORT, pp, pct, int } = X;
  const out = ["# Facts for the intensity deck", "", `Generated from the saved analysis of ${D.manifest.generated_at_singapore} (${D.manifest.selected_run_count} model–dataset runs).`, "",
    "`data.js` reads `research_paper/output/intensity_analysis.json`. This file is regenerated by `write_facts.js` during a presentation build. Analysis values and figures have one source in the research outputs. No model is run by this export.", "",
    "The benchmark is complete for ten models on sixteen datasets. The intensity comparison uses six eligible corpora and non-neutral reference clips with known native intensity. Percentages below retain one decimal; the slides may round to whole percentages. pp means percentage points.", "",
    "## Scope and definitions", "", "| Fact | Value | Source |", "| --- | --- | --- |",
    `| Models / corpus-model comparisons | ${S.models} / ${S.pairs} | contrast_rows |`,
    `| Raw strongest-minus-weakest change above zero | ${S.observedUp} / ${S.pairs} | contrast_rows.observed_change_pp |`,
    `| Acted comparisons with adjusted 95% interval above zero | ${S.actedUp} / ${S.actedFits} | contrast_rows.adjusted_ci_lower_pp |`,
    "| Adjustment | equal emotion weights, native intensity and log2 clip duration, within each corpus | effect_rows, manifest.parameters |",
    "| Intervals | speaker clusters, DailyTalk dialogue clusters, withheld below 20 clusters, exploratory and not corrected for multiple comparisons | manifest.parameters |",
    "| DailyTalk | two actors, 93 dialogue clusters, conditional on the sampled speakers | corpus documentation and effect_rows.nclusters |",
    "| Matched MEAD | three published take keys from two actors, transcript equivalence unverified, estimate suppressed | matched_rows and intensity_inventory_manifest.json |",
    "| Native scales | CREMA-D low/medium/high (one sentence), RAVDESS normal/strong, MEAD weak/medium/strong, THAI-SER scripted low/high, MCAE-SPPS listener mean 1–9, DailyTalk ECSS 1–3 | scope_rows, inventory manifest |",
    "| MCAE-SPPS | listener rating is distinct from loudness meanIntensity. Quartiles are display bins, not native categories | scope_rows |",
    "| Direct intensity estimation | untested. The saved benchmark predictions classify emotion categories | analysis_report/intensity_en.md |", ""];
  function table(title, source, header, body) {
    out.push(`## ${title}`, "", `Source: \`${source}\``, "", "| " + header.join(" | ") + " |", "| " + header.map(() => "---").join(" | ") + " |", ...body.map((r) => "| " + r.join(" | ") + " |"), "");
  }
  const p1 = (x) => x == null ? "—" : (100 * x).toFixed(1);
  const e = (v) => v == null ? "—" : v.toFixed(2);
  const ci = (lo, hi) => lo == null ? "withheld" : `[${e(lo)}, ${e(hi)}]`;
  table("Corpus scope", "output/intensity_scope_rows.csv", ["Corpus", "Total clips", "Known level", "Non-neutral known", "Clusters", "Levels"],
    D.scope_rows.map((r) => [DS[r.dataset], int(r.n_total), int(r.n_known), int(r.n_non_neutral_known), X.clusters[r.dataset], r.levels]));
  table("Summary counts", "output/intensity_contrast_rows.csv", ["Corpus", "Models", "Raw gains", "Adjusted up / crossing zero / down / withheld", "Matched up / down", "Matched keys"],
    Object.entries(S.byDataset).map(([ds, r]) => [DS[ds], r.n, r.observedUp, `${r.adjUp} / ${r.adjZero} / ${r.adjDown} / ${r.adjWithheld}`, `${r.matUp} / ${r.matDown}`, r.pairs]));
  table("Weakest to strongest", "output/intensity_contrast_rows.csv", ["Corpus", "Model", "Levels", "n weak / strong", "Accuracy weak / strong %", "Neutral answer weak / strong %", "Raw change pp", "Adjusted change pp [95% CI]", "Matched change pp [95% CI]"],
    C.map((r) => [DS[r.dataset], SHORT[r.model], `${r.low_label} to ${r.high_label}`, `${r.low_n} / ${r.high_n}`, `${p1(r.low_accuracy)} / ${p1(r.high_accuracy)}`, `${p1(r.low_neutral_rate)} / ${p1(r.high_neutral_rate)}`, e(r.observed_change_pp), `${e(r.adjusted_change_pp)} ${ci(r.adjusted_ci_lower_pp, r.adjusted_ci_upper_pp)}`, r.matched_pairs ? `${e(r.matched_difference_pp)} ${ci(r.matched_ci_lower_pp, r.matched_ci_upper_pp)}` : "—"]));
  table("Accuracy and label priors by level", "output/intensity_level_rows.csv", ["Corpus", "Model", "Level", "n", "Accuracy %", "Neutral answer %", "Angry answer %"],
    D.level_rows.map((r) => [DS[r.dataset], SHORT[r.model], r.level_label, r.n, p1(r.accuracy), p1(r.predicted_neutral_rate), p1(r.predicted_angry_rate)]));
  table("MEAD Qwen2-Audio recall", "output/intensity_class_rows.csv", ["Reference emotion", "Level", "n", "Recall %"],
    D.class_rows.filter((r) => r.dataset === "mead" && r.model === "qwen2_audio_7b").map((r) => [r.gold, r.level_label, r.n, p1(r.accuracy)]));
  fs.writeFileSync(path.join(__dirname, "facts.md"), out.join("\n") + "\n");
};
